const rawItems = $input.all().map((item) => item.json);
const history = rawItems.length === 1 && Array.isArray(rawItems[0]) ? rawItems[0] : rawItems;
if (!Array.isArray(history) || history.length === 0) {
  throw new Error("GPU history response must be a non-empty array");
}
const seenDates = new Set();
for (const row of history) {
  if (!row || typeof row !== "object") throw new Error("Snapshot must be an object");
  if (!/^\d{4}-\d{2}-\d{2}$/.test(row.date)) throw new Error("Invalid snapshot date: " + row.date);
  if (seenDates.has(row.date)) throw new Error("Duplicate snapshot date: " + row.date);
  seenDates.add(row.date);
  if (!row.prices || typeof row.prices !== "object" || Array.isArray(row.prices)) {
    throw new Error("Invalid prices map on " + row.date);
  }
  const prices = Object.entries(row.prices);
  if (prices.length === 0) throw new Error("Empty prices map on " + row.date);
  for (const [model, price] of prices) {
    if (typeof price !== "number" || !Number.isFinite(price) || price <= 0) {
      throw new Error("Invalid price for " + model + " on " + row.date);
    }
  }
  if (row.source !== undefined && row.source !== "live" && row.source !== "curated") {
    throw new Error("Invalid source on " + row.date);
  }
  if (row.meta !== undefined) {
    if (!row.meta || typeof row.meta !== "object" || Array.isArray(row.meta)) {
      throw new Error("Invalid metadata map on " + row.date);
    }
    for (const [model, meta] of Object.entries(row.meta)) {
      if (!(model in row.prices)) throw new Error("Metadata without price for " + model + " on " + row.date);
      if (!meta || typeof meta !== "object") throw new Error("Invalid metadata for " + model);
      if (typeof meta.low !== "number" || typeof meta.high !== "number" || meta.low <= 0 || meta.high < meta.low) {
        throw new Error("Invalid spread for " + model + " on " + row.date);
      }
      if (!Array.isArray(meta.sources) || meta.sources.length === 0 || !meta.sources.every((source) => typeof source === "string" && source.length > 0)) {
        throw new Error("Invalid sources for " + model + " on " + row.date);
      }
      if (!Number.isInteger(meta.n) || meta.n < 1) throw new Error("Invalid sample count for " + model + " on " + row.date);
    }
  }
}
const fileContent = JSON.stringify(history, null, 2) + "\n";
return [{ json: { fileContent, snapshotCount: history.length, lastDate: history.map((row) => row.date).sort().at(-1) } }];

const validated = $("Validate + serialize").first().json;
const today = new Date().toISOString().slice(0, 10);
const commitBody = {
  message: "GPU Prices: back up live history (" + today + ")",
  content: Buffer.from(validated.fileContent, "utf-8").toString("base64"),
  sha: $json.sha,
  branch: "main"
};
return [{ json: { commitBody, snapshotCount: validated.snapshotCount, lastDate: validated.lastDate } }];
